        desc: "Welcome to Edinburgh – The City of Lights! Your adventure begins with a smooth transfer from the airport to your hotel, where you'll be ready to immerse yourself in the magic of Edinburgh. Whether you're here for the art, the culture, the fashion, or the food, Edinburgh offers an abundance of experiences waiting to be explored. Overnight Stay in Edinburgh.",
