        title: "Glasgow – Glasgow 01 Day Hop on Hop off City tour on SIC Basis",
        desc: "Breakfast at Hotel. Glasgow 01 Day Hop on Hop off City bus. Meeting Point: Meeting point may vary depending on the option booked. Explore one of the most vibrant Scottish cities with a 1 or 2-day ticket to Glasgow's hop-on and hop-off bus. Explore museums, art galleries, parks, theatres and even Glasgow Cathedral. In addition, the city's pubs, cafés, bars and nightclubs help make Glasgow one of the new preferred destinations for short breaks. The visitor attractions and places of interest are spread throughout the city and the best way to visit the attractions and to see the city, is to step on one of the open-top tour buses for a fully guided tour round all the main sights. Jump off at any of the stops, conveniently located for the Gothic Cathedral, the Riverside Museum of Transport and Travel, the recently restored Kelvingrove Art Galleries, Glasgow University, Glasgow Green and Clydeside Distillery, among many other sights. Overnight Stay in Glasgow.",
