        desc: "After breakfast, catch a direct train from Amsterdam to Cologne. If you're looking for a quick, comfortable way to travel between two of Western Europe's vibrant cities, this train journey is ideal. On a high-speed train (such as ICE), the trip usually takes about 2 hours 37 minutes to 2 hours 40 minutes. You'll depart from Amsterdam's central station and arrive right at Cologne's main station. Overnight Stay in Cologne.",
